 let anchor="    let mut ids = BTreeMap::new();";assert_eq!(s.matches(anchor).count(),1);let extra=format!("    for name in[\"core-frozen\",\"libraries-frozen\",\"freeze-frozen\",\"link-frozen\"]{{let base=Path::new(\"{PRIOR}/native-initial\").join(name);let exit=read(base.join(\"exit.json\"));assert_eq!(exit[\"success\"],true);assert_eq!(hash(base.join(\"stdout.log\")),exit[\"stdout_sha256\"]);assert_eq!(hash(base.join(\"stderr.log\")),exit[\"stderr_sha256\"]);if name==\"core-frozen\"{{let t=read(base.join(\"tests.json\"));assert_eq!(t[\"passed_tests\"].as_array().unwrap().len(),129);assert_eq!(t[\"unfiltered\"],true);}}for f in[\"command.json\",\"exit.json\",\"stdout.log\",\"stderr.log\",\"tests.json\"]{{let p=base.join(f);pins.insert(p.display().to_string(),hash(p));}}}}\n{anchor}");s=s.replace(anchor,&extra);fs::write(r.join("capture.rs"),s).unwrap();
 let mut s=fs::read_to_string(Path::new(PRIOR).join("review.rs")).unwrap().replace(PRIOR,R).replace("build-plan-rest.json","build-plan.json").replace("paired_g2_borrowed","absolute_norm");
 let from="for step in read(r(\"build-plan.json\"))[\"steps\"].as_array().unwrap().iter().take(4)";let to=format!("for step in read(\"{PRIOR}/build-plan.json\")[\"steps\"].as_array().unwrap().iter().take(4)");assert_eq!(s.matches(from).count(),1);s=s.replace(from,&to);
