 let remove=" assert_eq!(read(r(\"native-initial/field-off/exit.json\"))[\"success\"],false);\n";assert_eq!(s.matches(remove).count(),1);s=s.replace(remove,"");fs::write(r.join("review.rs"),s).unwrap();
